// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        SuccessCallee helper = new SuccessCallee();
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for(uint i=0; i<_tos.length; i++){
            helper.prepare(from, _tos[i], v);
        }
        bool ok;
        try c.transfer(from, address(helper), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract SuccessCallee {
    mapping(bytes32 => bool) expected;
    function prepare(address from, address to, uint v) external {
        expected[keccak256(abi.encode(from, to, v))] = true;
    }
    fallback() external {
        (address from, address to, uint v) = abi.decode(msg.data[4:], (address, address, uint256));
        require(expected[keccak256(abi.encode(from, to, v))], "unexpected call");
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
}
